RED = True
BLACK = False

class RBNode:
    def __init__(self, key, value, color=RED, parent=None, left=None, right=None):
        self.key = key
        self.value = value
        self.color = color
        self.parent = parent
        self.left = left
        self.right = right

def rb_tree_search(items: list[tuple[int, str]], query_key: int) -> str | None:
    """Builds a Red-Black BST index from (key, value) pairs and retrieves value for query key in O(log N)."""
    NIL = RBNode(key=None, value=None, color=BLACK)
    root = NIL

    def left_rotate(x):
        nonlocal root
        y = x.right
        x.right = y.left
        if y.left != NIL:
            y.left.parent = x
        y.parent = x.parent
        if x.parent is None:
            root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def right_rotate(y):
        nonlocal root
        x = y.left
        y.left = x.right
        if x.right != NIL:
            x.right.parent = y
        x.parent = y.parent
        if y.parent is None:
            root = x
        elif y == y.parent.right:
            y.parent.right = x
        else:
            y.parent.left = x
        x.right = y
        y.parent = x

    def insert_fixup(z):
        nonlocal root
        while z.parent and z.parent.color == RED:
            if z.parent == z.parent.parent.left:
                y = z.parent.parent.right
                if y.color == RED:
                    z.parent.color = BLACK
                    y.color = BLACK
                    z.parent.parent.color = RED
                    z = z.parent.parent
                else:
                    if z == z.parent.right:
                        z = z.parent
                        left_rotate(z)
                    z.parent.color = BLACK
                    z.parent.parent.color = RED
                    right_rotate(z.parent.parent)
            else:
                y = z.parent.parent.left
                if y.color == RED:
                    z.parent.color = BLACK
                    y.color = BLACK
                    z.parent.parent.color = RED
                    z = z.parent.parent
                else:
                    if z == z.parent.left:
                        z = z.parent
                        right_rotate(z)
                    z.parent.color = BLACK
                    z.parent.parent.color = RED
                    left_rotate(z.parent.parent)
        root.color = BLACK

    for k, v in items:
        z = RBNode(key=k, value=v, color=RED, left=NIL, right=NIL)
        y = None
        x = root
        while x != NIL:
            y = x
            if z.key < x.key:
                x = x.left
            elif z.key > x.key:
                x = x.right
            else:
                x.value = v
                z = None
                break
        if z is not None:
            z.parent = y
            if y is None:
                root = z
            elif z.key < y.key:
                y.left = z
            else:
                y.right = z
            insert_fixup(z)

    curr = root
    while curr != NIL:
        if query_key == curr.key:
            return curr.value
        elif query_key < curr.key:
            curr = curr.left
        else:
            curr = curr.right
    return None
